source='''from collections import Counter

def _runs(values):
    out = []
    i = 0
    while i < len(values):
        if values[i] == 0:
            i += 1
            continue
        j = i
        while j + 1 < len(values) and values[j + 1] != 0:
            j += 1
        out.append((i, j))
        i = j + 1
    return out

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    rr, cc = _runs([g[r][0] for r in range(h)]), _runs([g[0][c] for c in range(w)])
    rh = Counter(b-a+1 for a,b in rr).most_common(1)[0][0]
    cw = Counter(b-a+1 for a,b in cc).most_common(1)[0][0]
    rr = [(a,b) for a,b in rr if b-a+1 == rh]
    cc = [(a,b) for a,b in cc if b-a+1 == cw]
    if rh < 3 or cw < 3:
        return g
    centers = []
    for ri,(r0,r1) in enumerate(rr):
        row=[]
        for ci,(c0,c1) in enumerate(cc):
            row.append(g[(r0+r1)//2][(c0+c1)//2])
        centers.append(row)
    counts=Counter(x for row in centers for x in row)
    if not counts:
        return g
    background=counts.most_common(1)[0][0]
    for color in counts:
        if color == background:
            continue
        # Join consecutive occurrences of this color in each tile row.
        for ri,row in enumerate(centers):
            cols=[ci for ci,x in enumerate(row) if x==color]
            for a,b in zip(cols,cols[1:]):
                r0,r1=rr[ri]
                for c in range(cc[a][1]+1, cc[b][0]):
                    for r in range(r0+1,r1):
                        if g[r][c]==0: g[r][c]=color
        # Join consecutive occurrences in each tile column.
        for ci in range(len(cc)):
            rows=[ri for ri in range(len(rr)) if centers[ri][ci]==color]
            for a,b in zip(rows,rows[1:]):
                c0,c1=cc[ci]
                for r in range(rr[a][1]+1, rr[b][0]):
                    for c in range(c0+1,c1):
                        if g[r][c]==0: g[r][c]=color
    return g
